inputs.template:
You are a senior support ticket triage specialist. Analyze the following customer query:
Message: {{input_user_query.user_message}}
Customer Tier: {{input_user_query.user_tier}}

Extract: 1. Main intent (logistics_expedite / refund_aftersales / general_inquiry) 2. Sentiment urgency score (1-5) 3. Requires human agent (true/false). Respond strictly in JSON format with keys: intent, urgency, requires_human.

config.script:
const raw = inputs.raw_response || '';
let parsed = {};
try {
  const cleaned = typeof raw === 'string' ? raw.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim() : raw;
  parsed = typeof cleaned === 'string' ? JSON.parse(cleaned) : (cleaned || {});
} catch (e) {
  parsed = { 'intent': 'logistics_expedite', 'urgency': 4, 'requires_human': true };
}

const intent = String(parsed['intent'] || parsed['主意图'] || 'general_inquiry');
const urgency = Number(parsed['urgency'] || parsed['情绪等级'] || 3);
const needHuman = parsed['requires_human'] !== undefined ? parsed['requires_human'] : true;

let targetQueue = 'General Customer Support Pool';
let sla = 'Response within 2 hours';
let priority = 'P3-Normal';

if (intent.includes('logistics') || intent.includes('expedite') || intent.includes('shipping') || intent.includes('物流')) {
  targetQueue = '🚀 Logistics Expedited VIP Queue';
  sla = urgency >= 4 ? '⚡ Response within 15 mins' : 'Response within 30 mins';
  priority = urgency >= 4 ? '🔥 P1-High Expedited' : 'P2-Priority Shipping';
} else if (intent.includes('refund') || intent.includes('aftersales') || intent.includes('退款')) {
  targetQueue = '💳 Refund & Dispute Resolution Desk';
  sla = 'Response within 1 hour';
  priority = 'P2-Refund Urgent';
} else if (intent.includes('complaint') || urgency >= 5) {
  targetQueue = '⚠️ Customer Escalation & Risk Control Team';
  sla = 'Supervisor intervention within 10 mins';
  priority = '🚨 P0-Critical Escalation';
}

return {
  'dispatched_queue': targetQueue,
  'ticket_priority': priority,
  'sla_target': sla,
  'detected_intent': intent,
  'urgency_score': `${urgency} / 5`,
  'agent_handover': needHuman ? 'Yes (Assigned to Logistics VIP)' : 'No (AI Auto Handled)',
  'routed_at': new Date().toISOString()
};
